"""DIAGPROG5 V104: instalador compatible con Actualizaciones de V103.

No ejecuta nada al importarse. Usa la base local comprobada, no descarga claves
ni publica ni elimina anuncios durante la instalación.
"""
import ast
import hashlib
import os
from pathlib import Path
import runpy
import shutil
import tempfile
import time

TARGET_VERSION = '104'
OUTPUT_NAME = 'bot_wallapop_profesional_v104_ADMIN_BORRADO.py'
BASE_HASH = 'd81680c3e87b25bdc5cf124ef9b31a4c37f7b54f273a9fd0b6a0658f0805e504'
PANEL_SOURCE = '"""Panel manual de borrado. Importar no abre Chrome ni elimina anuncios."""\nimport copy\nimport json\nimport math\nimport os\nimport queue\nimport re\nimport threading\nimport time\nfrom collections import Counter\nfrom datetime import datetime\nfrom pathlib import Path\nfrom urllib.parse import urlparse, unquote\n\n\ndef escribir_json(path, value):\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    temp = path.with_name(path.name + \'.tmp\')\n    temp.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding=\'utf-8\')\n    os.replace(temp, path)\n\n\ndef bloquear(path):\n    """Bloqueo liberado por el SO también si el programa se cierra."""\n    handle = open(path, \'a+b\')\n    try:\n        if handle.tell() == 0:\n            handle.write(b\'0\')\n            handle.flush()\n        handle.seek(0)\n        if os.name == \'nt\':\n            import msvcrt\n            msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)\n        else:\n            import fcntl\n            fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)\n        return handle\n    except Exception:\n        handle.close()\n        raise RuntimeError(\'Otro lote está en curso. Cierra las otras instancias de DIAGPROG5.\')\n\n\ndef fecha(item):\n    for key in (\'timestamp_publicado\', \'timestamp\', \'created_at_ts\', \'fecha_ts\'):\n        try:\n            n = float(item.get(key, 0))\n            if n > 100_000_000_000:\n                n /= 1000\n            if math.isfinite(n) and n > 0:\n                return n\n        except (TypeError, ValueError):\n            pass\n    value = str(item.get(\'fecha\') or item.get(\'fecha_publicacion\') or \'\').strip()\n    try:\n        return datetime.fromisoformat(value.replace(\'Z\', \'+00:00\')).timestamp()\n    except ValueError:\n        pass\n    for fmt in (\'%d/%m/%Y %H:%M:%S\', \'%d/%m/%Y %H:%M\', \'%Y-%m-%d %H:%M:%S\'):\n        try:\n            return datetime.strptime(value, fmt).timestamp()\n        except ValueError:\n            pass\n    return None\n\n\ndef identidad(url):\n    try:\n        u = urlparse(str(url))\n        host = (u.hostname or \'\').lower()\n        if u.scheme != \'https\' or not (host == \'wallapop.com\' or host.endswith(\'.wallapop.com\')):\n            return None\n        if u.username or u.password or u.port not in (None, 443):\n            return None\n        # Un ID estable impide confundir títulos repetidos.\n        m = re.fullmatch(r\'/item/(?:[^/]*-)?([0-9]+)/*\', unquote(u.path))\n        return m.group(1) if m else None\n    except (ValueError, TypeError):\n        return None\n\n\ndef enlace(item):\n    for key in (\'url\', \'url_anuncio\', \'url_wallapop\', \'link\', \'permalink\', \'web_url\'):\n        value = str(item.get(key) or \'\').strip()\n        if identidad(value):\n            return value\n    return \'\'\n\n\ndef validar(cantidad, horas, pausa, fallos):\n    count, age, delay, errors = int(cantidad), float(horas), float(pausa), int(fallos)\n    if not 1 <= count <= 500:\n        raise ValueError(\'La cantidad debe estar entre 1 y 500.\')\n    if not math.isfinite(age) or not 0 <= age <= 87600:\n        raise ValueError(\'La antigüedad debe estar entre 0 y 87600 horas.\')\n    if not math.isfinite(delay) or not 1 <= delay <= 120:\n        raise ValueError(\'La pausa debe estar entre 1 y 120 segundos.\')\n    if not 1 <= errors <= 20:\n        raise ValueError(\'El límite de fallos debe estar entre 1 y 20.\')\n    return dict(cantidad=count, horas=age, pausa=delay, fallos=errors)\n\n\ndef seleccionar(datos, cfg, bloqueados=(), ahora=None):\n    ahora = time.time() if ahora is None else ahora\n    if not isinstance(datos, dict):\n        raise ValueError(\'El registro de publicados no es válido.\')\n    duplicados = Counter(identidad(enlace(x)) for x in datos.values() if isinstance(x, dict))\n    resultado, omitidos = [], Counter()\n    for key, item in datos.items():\n        if not isinstance(item, dict):\n            continue\n        if any(item.get(k) for k in (\'protegido\', \'protegido_rotacion\', \'proteger\', \'locked\', \'bloqueado\')):\n            omitidos[\'protegidos\'] += 1\n            continue\n        if item.get(\'eliminado_wallapop\') or str(item.get(\'estado\', \'PUBLICADO\')).upper() not in (\'PUBLICADO\', \'ACTIVO\', \'ONLINE\', \'\'):\n            omitidos[\'inactivos\'] += 1\n            continue\n        stamp = fecha(item)\n        if stamp is None or not math.isfinite(stamp) or stamp <= 0 or stamp > ahora:\n            omitidos[\'sin fecha válida\'] += 1\n            continue\n        if ahora - stamp < cfg[\'horas\'] * 3600:\n            omitidos[\'demasiado recientes\'] += 1\n            continue\n        url = enlace(item)\n        uid = identidad(url)\n        if not uid:\n            omitidos[\'sin enlace identificable\'] += 1\n            continue\n        if duplicados[uid] > 1:\n            omitidos[\'enlace duplicado\'] += 1\n            continue\n        if uid in bloqueados:\n            omitidos[\'pendientes de revisión\'] += 1\n            continue\n        resultado.append(dict(registro=key, item=copy.deepcopy(item), url=url, uid=uid,\n                              fecha=stamp, titulo=str(item.get(\'titulo\') or item.get(\'title\') or \'(sin título)\')))\n    resultado.sort(key=lambda x: (x[\'fecha\'], str(x[\'registro\'])))\n    return resultado[:cfg[\'cantidad\']], dict(omitidos), len(resultado)\n\n\ndef respuesta_borrado(response, uid):\n    u = urlparse(response.url)\n    host = (u.hostname or \'\').lower()\n    return (response.request.method.upper() == \'DELETE\' and 200 <= response.status < 300\n            and (host == \'wallapop.com\' or host.endswith(\'.wallapop.com\'))\n            and uid in unquote(u.path).split(\'/\'))\n\n\nclass Cancelado(Exception):\n    pass\n\n\ndef boton_unico(scope, patron):\n    matches = []\n    for role in (\'button\', \'menuitem\'):\n        loc = scope.get_by_role(role, name=re.compile(patron, re.I))\n        for n in range(loc.count()):\n            el = loc.nth(n)\n            if el.is_visible() and el.is_enabled():\n                matches.append(el)\n    return matches[0] if len(matches) == 1 else None\n\n\ndef eliminar(page, entry, stop):\n    """Sin búsqueda por título, clicks forzados ni fallback de borrado antiguo."""\n    if stop.is_set():\n        raise Cancelado()\n    page.goto(entry[\'url\'], wait_until=\'domcontentloaded\', timeout=35000)\n    page.wait_for_timeout(1600)\n    if identidad(page.url) != entry[\'uid\']:\n        raise RuntimeError(\'El enlace no abrió el anuncio previsto. No se ha pulsado borrar.\')\n    button = boton_unico(page, r\'^(eliminar|borrar|delete)( (este )?(anuncio|producto|artículo|item))?$|^papelera$\')\n    if button is None:\n        menu = boton_unico(page, r\'^(más opciones|opciones|más|more|more options|acciones)$\')\n        if menu:\n            menu.click(timeout=4000)\n            page.wait_for_timeout(400)\n            button = boton_unico(page, r\'^(eliminar|borrar|delete)( (este )?(anuncio|producto|artículo|item))?$\')\n    if button is None:\n        raise RuntimeError(\'No se encontró un control de borrado inequívoco; se guardará un diagnóstico.\')\n    confirmed = []\n    def response_handler(response):\n        if respuesta_borrado(response, entry[\'uid\']):\n            confirmed.append(True)\n    page.on(\'response\', response_handler)\n    try:\n        if stop.is_set():\n            raise Cancelado()\n        button.click(timeout=5000)\n        page.wait_for_timeout(700)\n        dialogs = page.get_by_role(\'dialog\')\n        visible = [dialogs.nth(i) for i in range(dialogs.count()) if dialogs.nth(i).is_visible()]\n        if len(visible) == 1:\n            confirm = boton_unico(visible[0], r\'^(sí,? )?(eliminar|borrar|delete)( (este )?(anuncio|producto|artículo|item))?$|^confirmar$\')\n            if confirm:\n                if stop.is_set():\n                    raise Cancelado()\n                confirm.click(timeout=5000)\n        for _ in range(24):\n            if confirmed:\n                return\n            page.wait_for_timeout(250)\n        raise RuntimeError(\'Borrado no verificado por respuesta del servidor. Revisar el anuncio antes de repetir.\')\n    finally:\n        page.remove_listener(\'response\', response_handler)\n\n\nclass Panel:\n    def __init__(self, g):\n        import customtkinter as ctk\n        from tkinter import ttk, messagebox\n        self.g, self.ctk, self.msg = g, ctk, messagebox\n        self.root = g[\'ventana\']\n        self.data = Path(g[\'CARPETA_DATOS_USUARIO\']) / \'borrado_antiguos\'\n        self.data.mkdir(parents=True, exist_ok=True)\n        self.stop, self.events = threading.Event(), queue.Queue()\n        self.busy, self.plan, self.settings = False, [], None\n        self.journal_path = self.data / \'historial.json\'\n        self.history = self.read(self.journal_path, [])\n        if not isinstance(self.history, list):\n            raise ValueError(\'Historial de borrado inválido: revisar antes de continuar.\')\n        cfg = self.read(self.data / \'ajustes.json\', dict(cantidad=5, horas=24, pausa=3, fallos=1))\n        tab = g[\'tabs\'].add(\'Borrar antiguos\')\n        scroll = ctk.CTkScrollableFrame(tab)\n        scroll.pack(fill=\'both\', expand=True)\n        ctk.CTkLabel(scroll, text=\'Borrar los anuncios más antiguos\', font=(\'Segoe UI\', 22, \'bold\')).pack(anchor=\'w\', padx=16, pady=10)\n        ctk.CTkLabel(scroll, text=\'Orden por fecha registrada en DIAGPROG5. Solo anuncios activos, sin protección y con enlace identificable.\\nEl borrado se inicia aquí; la rotación automática al publicar está desactivada.\', wraplength=780, justify=\'left\').pack(anchor=\'w\', padx=16)\n        form = ctk.CTkFrame(scroll)\n        form.pack(fill=\'x\', padx=16, pady=12)\n        self.inputs = {}\n        for row, (key, label) in enumerate(((\'cantidad\', \'Máximo a borrar por lote (1–500)\'), (\'horas\', \'Antigüedad mínima en horas\'), (\'pausa\', \'Pausa entre anuncios en segundos (1–120)\'), (\'fallos\', \'Detener tras estos fallos consecutivos (1–20)\'))):\n            ctk.CTkLabel(form, text=label).grid(row=row, column=0, padx=12, pady=5, sticky=\'w\')\n            field = ctk.CTkEntry(form, width=110)\n            field.insert(0, str(cfg.get(key, {\'cantidad\':5, \'horas\':24, \'pausa\':3, \'fallos\':1}[key])))\n            field.grid(row=row, column=1, padx=12, pady=5)\n            self.inputs[key] = field\n        actions = ctk.CTkFrame(scroll)\n        actions.pack(fill=\'x\', padx=16)\n        self.preview_button = ctk.CTkButton(actions, text=\'1. Vista previa\', command=self.preview)\n        self.preview_button.pack(side=\'left\', padx=6, pady=8)\n        self.start_button = ctk.CTkButton(actions, text=\'2. Borrar lote mostrado\', command=self.start, fg_color=\'#a63838\', state=\'disabled\')\n        self.start_button.pack(side=\'left\', padx=6)\n        self.stop_button = ctk.CTkButton(actions, text=\'Detener\', command=self.cancel, state=\'disabled\')\n        self.stop_button.pack(side=\'left\', padx=6)\n        table_frame = ctk.CTkFrame(scroll)\n        table_frame.pack(fill=\'x\', padx=16, pady=10)\n        self.table = ttk.Treeview(table_frame, columns=(\'title\', \'date\', \'id\'), show=\'headings\', height=9)\n        for key, title, width in ((\'title\', \'Anuncio\', 350), (\'date\', \'Fecha registrada\', 160), (\'id\', \'ID Wallapop\', 130)):\n            self.table.heading(key, text=title)\n            self.table.column(key, width=width)\n        bar = ttk.Scrollbar(table_frame, orient=\'vertical\', command=self.table.yview)\n        self.table.configure(yscrollcommand=bar.set)\n        self.table.pack(side=\'left\', fill=\'both\', expand=True)\n        bar.pack(side=\'right\', fill=\'y\')\n        self.status = ctk.CTkLabel(scroll, text=\'Ajusta la cantidad y pulsa Vista previa.\', wraplength=780, justify=\'left\')\n        self.status.pack(anchor=\'w\', padx=16, pady=5)\n        self.progress = ctk.CTkProgressBar(scroll)\n        self.progress.set(0)\n        self.progress.pack(fill=\'x\', padx=16, pady=6)\n        self.log = ctk.CTkTextbox(scroll, height=150)\n        self.log.pack(fill=\'x\', padx=16, pady=8)\n        self.log.configure(state=\'disabled\')\n        ctk.CTkButton(scroll, text=\'Abrir historial y diagnósticos\', command=lambda: os.startfile(str(self.data))).pack(anchor=\'w\', padx=16, pady=6)\n        self.root.after(150, self.poll)\n\n    @staticmethod\n    def read(path, default):\n        return json.loads(path.read_text(encoding=\'utf-8\')) if path.exists() else default\n\n    def bloqueados(self):\n        return {x[\'uid\'] for x in self.history if x.get(\'estado\') in (\'EN_CURSO\', \'REVISAR\', \'ELIMINADO\')}\n\n    def config(self):\n        return validar(*(self.inputs[k].get() for k in (\'cantidad\', \'horas\', \'pausa\', \'fallos\')))\n\n    def preview(self):\n        if self.busy:\n            return\n        self.start_button.configure(state=\'disabled\')\n        self.plan = []\n        try:\n            cfg = self.config()\n            plan, omitidos, total = seleccionar(self.g[\'cargar_publicados\'](), cfg, self.bloqueados())\n            escribir_json(self.data / \'ajustes.json\', cfg)\n            self.settings, self.plan = cfg, plan\n            for key in self.table.get_children():\n                self.table.delete(key)\n            for entry in plan:\n                self.table.insert(\'\', \'end\', values=(entry[\'titulo\'], datetime.fromtimestamp(entry[\'fecha\']).strftime(\'%d/%m/%Y %H:%M\'), entry[\'uid\']))\n            omissions = \', \'.join(f\'{k}: {v}\' for k, v in omitidos.items()) or \'ninguno\'\n            self.status.configure(text=f\'{len(plan)} en este lote · {total} elegibles. Omitidos: {omissions}.\')\n            self.start_button.configure(state=\'normal\' if plan else \'disabled\')\n        except Exception as e:\n            self.msg.showerror(\'Vista previa\', str(e))\n\n    def start(self):\n        if self.busy or not self.plan:\n            return\n        try:\n            if self.config() != self.settings:\n                raise ValueError(\'Has cambiado los ajustes. Genera otra vista previa.\')\n            if self.g.get(\'cola_en_ejecucion\') or any(self.g.get(k) for k in (\'_ROTACION_V102_EN_CURSO\', \'_ROTACION_V101_EN_CURSO\', \'_PUBLICACION_V104_EN_CURSO\')):\n                raise ValueError(\'Detén la cola y espera a que termine la operación actual.\')\n            latest, _, _ = seleccionar(self.g[\'cargar_publicados\'](), self.settings, self.bloqueados())\n            if latest != self.plan:\n                raise ValueError(\'El registro ha cambiado. Genera otra vista previa.\')\n            if not self.msg.askyesno(\'Confirmar borrado\', f\'Se intentará eliminar hasta {len(self.plan)} anuncios, en el orden mostrado.\\n\\nLa copia local no permite restaurarlos en Wallapop. ¿Continuar?\'):\n                return\n            self.busy = True\n            self.g[\'_BORRADO_V104_EN_CURSO\'] = True\n            self.stop.clear()\n            for widget in [self.preview_button, self.start_button, *self.inputs.values()]:\n                widget.configure(state=\'disabled\')\n            self.stop_button.configure(state=\'normal\')\n            self.progress.set(0)\n            threading.Thread(target=self.worker, args=(copy.deepcopy(self.plan), dict(self.settings)), daemon=True).start()\n        except Exception as e:\n            self.msg.showerror(\'Borrado\', str(e))\n\n    def cancel(self):\n        self.stop.set()\n        self.status.configure(text=\'Deteniendo: se comprobará el resultado de cualquier borrado ya enviado.\')\n\n    def worker(self, plan, cfg):\n        ok = errors = consecutive = done = 0\n        page = lock = None\n        session = self.data / (\'lote_\' + datetime.now().strftime(\'%Y%m%d_%H%M%S_%f\'))\n        try:\n            lock = bloquear(self.data / \'lote.lock\')\n            self.history = self.read(self.journal_path, [])\n            session.mkdir()\n            escribir_json(session / \'plan.json\', plan)\n            from playwright.sync_api import sync_playwright\n            with sync_playwright() as p:\n                browser = p.chromium.connect_over_cdp(\'http://127.0.0.1:9222\', timeout=15000)\n                if not browser.contexts:\n                    raise RuntimeError(\'Chrome no tiene una sesión disponible.\')\n                page = browser.contexts[0].new_page()\n                try:\n                    for entry in plan:\n                        if self.stop.is_set():\n                            break\n                        event = None\n                        try:\n                            current = self.g[\'cargar_publicados\']()\n                            one, _, _ = seleccionar(current, dict(cfg, cantidad=500), self.bloqueados())\n                            if entry not in one:\n                                raise RuntimeError(\'El anuncio cambió o ya no es elegible. No se ha borrado.\')\n                            event = dict(uid=entry[\'uid\'], registro=entry[\'registro\'], titulo=entry[\'titulo\'], fecha=datetime.now().isoformat(), estado=\'EN_CURSO\')\n                            self.history.append(event)\n                            escribir_json(self.journal_path, self.history)\n                            self.events.put((\'log\', f"Procesando: {entry[\'titulo\']} · {entry[\'uid\']}"))\n                            eliminar(page, entry, self.stop)\n                            # Registrar primero la confirmación remota: jamás reintentar si falla el guardado local.\n                            event[\'estado\'] = \'ELIMINADO\'\n                            escribir_json(self.journal_path, self.history)\n                            current = self.g[\'cargar_publicados\']()\n                            record = current.get(entry[\'registro\'])\n                            if not isinstance(record, dict) or identidad(enlace(record)) != entry[\'uid\']:\n                                raise RuntimeError(\'Eliminado en Wallapop; el registro local cambió. Revisar manualmente.\')\n                            record.update(estado=\'ELIMINADO_ROTACION\', eliminado_wallapop=True, fecha_eliminacion_wallapop=datetime.now().strftime(\'%d/%m/%Y %H:%M:%S\'))\n                            escribir_json(Path(self.g[\'ARCHIVO_PUBLICADOS\']), current)\n                            ok += 1\n                            consecutive = 0\n                            self.events.put((\'log\', \'Eliminado y verificado: \' + entry[\'titulo\']))\n                        except Cancelado:\n                            if event:\n                                event[\'estado\'] = \'REVISAR\'\n                                event[\'detalle\'] = \'Interrumpido; comprobar estado antes de repetir.\'\n                                escribir_json(self.journal_path, self.history)\n                            break\n                        except Exception as e:\n                            errors += 1\n                            consecutive += 1\n                            if event:\n                                if event[\'estado\'] != \'ELIMINADO\':\n                                    event[\'estado\'] = \'REVISAR\'\n                                event[\'detalle\'] = str(e)\n                                escribir_json(self.journal_path, self.history)\n                            self.events.put((\'log\', f"Revisar {entry[\'titulo\']}: {e}"))\n                            try:\n                                diagnostic = session / entry[\'uid\']\n                                diagnostic.mkdir(exist_ok=True)\n                                page.screenshot(path=str(diagnostic / \'detalle.png\'), full_page=True)\n                                (diagnostic / \'detalle.html\').write_text(page.content(), encoding=\'utf-8\')\n                            except Exception:\n                                pass\n                        done += 1\n                        self.events.put((\'progress\', (done / len(plan), f\'{done}/{len(plan)} revisados · {ok} eliminados · {errors} incidencias\')))\n                        if consecutive >= cfg[\'fallos\'] or self.stop.wait(cfg[\'pausa\']):\n                            break\n                finally:\n                    page.close()\n        except Exception as e:\n            errors += 1\n            self.events.put((\'log\', \'Lote detenido: \' + str(e)))\n        finally:\n            if lock is not None:\n                lock.close()\n            self.events.put((\'done\', f\'Finalizado: {ok} eliminados, {errors} incidencias. Historial: {session.name}\'))\n\n    def poll(self):\n        try:\n            while True:\n                kind, value = self.events.get_nowait()\n                if kind == \'log\':\n                    self.log.configure(state=\'normal\')\n                    self.log.insert(\'end\', value + \'\\n\')\n                    self.log.see(\'end\')\n                    self.log.configure(state=\'disabled\')\n                elif kind == \'progress\':\n                    self.progress.set(value[0])\n                    self.status.configure(text=value[1])\n                elif kind == \'done\':\n                    self.busy = False\n                    self.g[\'_BORRADO_V104_EN_CURSO\'] = False\n                    self.plan = []\n                    self.status.configure(text=value)\n                    self.stop_button.configure(state=\'disabled\')\n                    for widget in [self.preview_button, *self.inputs.values()]:\n                        widget.configure(state=\'normal\')\n        except queue.Empty:\n            pass\n        self.root.after(150, self.poll)\n\n\ndef instalar_panel(g):\n    # La v104 separa el borrado del límite de publicación desde el arranque.\n    old_config = g[\'cargar_config_rotacion\']\n    def manual_config():\n        cfg = old_config()\n        cfg[\'activo\'] = False\n        return cfg\n    g[\'cargar_config_rotacion\'] = manual_config\n    g[\'_v102_rotacion_activa\'] = lambda: False\n    g[\'gestionar_rotacion_limite_wallapop\'] = lambda *a, **kw: (False, \'Usa la pestaña Borrar antiguos.\')\n    g[\'var_rotacion_activa\'].set(False)\n    # Comprobación dentro de funciones usadas también por botones ya creados.\n    g[\'_BORRADO_V104_EN_CURSO\'] = False\n    g[\'_PUBLICACION_V104_EN_CURSO\'] = False\n    publicar = g[\'_publicar_wallapop_hilo\']\n    def publicar_vigilado(*args, **kwargs):\n        g[\'_PUBLICACION_V104_EN_CURSO\'] = True\n        try:\n            if g.get(\'_BORRADO_V104_EN_CURSO\'):\n                return\n            return publicar(*args, **kwargs)\n        finally:\n            g[\'_PUBLICACION_V104_EN_CURSO\'] = False\n    g[\'_publicar_wallapop_hilo\'] = publicar_vigilado\n    g[\'_panel_borrado_v104\'] = Panel(g)\n'


def replace_once(source, before, after):
    if source.count(before) != 1:
        raise RuntimeError('La base instalada no coincide con V103; no se ha modificado.')
    return source.replace(before, after, 1)


def construir(text):
    if hashlib.sha256(text.encode('utf-8')).hexdigest() != BASE_HASH:
        raise RuntimeError('V103 tiene cambios no incluidos en esta actualización. Conserva esa versión y envíala para adaptarla.')
    text = replace_once(text, 'import shutil\n', 'import shutil\nimport zipfile\n')
    text = replace_once(text, '("Publicación", publicar_anuncio_wallapop)', '("Publicación", globals().get("publicar_anuncio_directamente"))')
    text = replace_once(text, 'def version_actual_bot():\n    return "103"', 'def version_actual_bot():\n    return "104"')
    guard = "    if globals().get('_BORRADO_V104_EN_CURSO', False):\n        messagebox.showinfo('Borrado en curso', 'Espera a que termine el lote antes de publicar.')\n        return\n\n"
    anchor = '    validacion_ok, _errores = validar_anuncio_antes_de_wallapop(\n'
    text = replace_once(text, anchor, guard + anchor)
    anchor = '    global cola_inicio_sesion, cola_publicados_sesion, cola_errores_sesion\n'
    text = replace_once(text, anchor, anchor + '\n' + guard)
    # El Worker histórico anuncia update_available=True también para quien
    # ya está actualizado. La comparación de versiones evita reinstalaciones.
    before = '''        disponible = bool(
            manifest.get(
                "update_available",
                disponible_por_version
            )
        ) or disponible_por_version'''
    text = replace_once(text, before, '        disponible = disponible_por_version')
    embedded = ('# V104 PANEL INCORPORADO: no requiere archivos .py adicionales.\n'
                'import types as _v104_types\n'
                '_v104_panel_module = _v104_types.ModuleType("borrado_antiguos_v104")\n'
                'exec(compile(' + repr(PANEL_SOURCE) + ', "<panel_borrado_v104>", "exec"), _v104_panel_module.__dict__)\n'
                '_v104_panel_module.instalar_panel(globals())\n')
    text = replace_once(text, 'ventana.mainloop()\n', embedded + 'ventana.mainloop()\n')
    compile(text, OUTPUT_NAME, 'exec')
    return text


def version(text):
    try:
        tree = ast.parse(text)
        for node in tree.body:
            if isinstance(node, ast.FunctionDef) and node.name == 'version_actual_bot':
                return int(node.body[0].value.value)
    except (ValueError, SyntaxError, AttributeError, TypeError, IndexError):
        pass
    return 0


def localizar(data):
    matches = []
    seen = set()
    roots = (data / 'versiones', data / 'actualizaciones', data / 'backups_actualizaciones', Path(__file__).resolve().parent)
    for root in roots:
        if not root.exists():
            continue
        for p in root.rglob('*.py'):
            try:
                resolved = p.resolve()
                if resolved in seen or 'bootstrap' in p.name.lower() or p.stat().st_size < 350000:
                    continue
                seen.add(resolved)
                text = p.read_text(encoding='utf-8')
                number = version(text)
                if number > 104:
                    raise RuntimeError('Hay una versión posterior a V104. Se cancela para no retroceder.')
                if number == 103:
                    matches.append((p.stat().st_mtime, resolved, text))
            except (OSError, UnicodeError):
                continue
    if not matches:
        raise RuntimeError('No encontré la V103 completa compatible en las carpetas del bot. No se ha cambiado tu instalación.')
    _, source, text = max(matches, key=lambda x: x[0])
    return source, text


def instalar(data):
    """Prepara archivos en una carpeta nueva; no ejecuta el bot."""
    data = Path(data)
    source, text = localizar(data)
    result = construir(text)
    banner_name = 'banner_dp5_limpio_v15.png'
    banner = next((p for p in (source.parent / banner_name, data / 'assets' / banner_name)
                   if p.is_file()), None)
    if banner is None:
        raise RuntimeError('No se encontró el banner de la instalación. No se abrirá una versión incompleta.')
    versions = data / 'versiones'
    versions.mkdir(parents=True, exist_ok=True)
    dest = Path(tempfile.mkdtemp(prefix='V104_' + time.strftime('%Y%m%d_%H%M%S') + '_', dir=versions))
    output = dest / OUTPUT_NAME
    output.write_text(result, encoding='utf-8', newline='\n')
    shutil.copy2(banner, dest / banner_name)
    # Conserva los archivos locales que el bot resuelve respecto a su carpeta;
    # los registros globales en AppData siguen usando las rutas originales.
    for path in source.parent.glob('*.json'):
        if path.is_file():
            shutil.copy2(path, dest / path.name)
    return output


def main():
    root = Path(os.environ.get('LOCALAPPDATA') or os.environ.get('APPDATA') or Path.home())
    output = instalar(root / 'DIAGPROG5')
    os.chdir(output.parent)
    runpy.run_path(str(output), run_name='__main__')


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        import tkinter as tk
        from tkinter import messagebox
        window = tk.Tk()
        window.withdraw()
        messagebox.showerror('DIAGPROG5 · Actualización V104', str(error))
        window.destroy()
        raise
